import{_ as e,C as t,c as r,o as i,j as a,b as l,a0 as n,a as s,w as d,G as o,a1 as g}from"./chunks/framework.DKRgXLPU.js";const m=JSON.parse('{"title":"SMART-mål for petanque","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/goals/smart-goals.md","filePath":"da/education/goals/smart-goals.md"}');const p=e({name:"da/education/goals/smart-goals.md"},[["render",function(e,m,p,u,h,k){const f=t("Mermaid");return i(),r("div",null,[m[1]||(m[1]=a("h1",{id:"smart-mal-for-petanque",tabindex:"-1"},[s("SMART-mål for petanque "),a("a",{class:"header-anchor",href:"#smart-mal-for-petanque","aria-label":'Permalink to "SMART-mål for petanque"'},"​")],-1)),m[2]||(m[2]=a("p",null,"SMART-rammen omdanner vage ønsker til handlingsrettede mål. Lad os se nærmere på hvert element med specifikke eksempler til petanque.",-1)),m[3]||(m[3]=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"Den store idé"),a("p",null,[a("strong",null,"Vage mål fører til vage resultater."),s(' SMART-mål skaber klarhed, handling og målbar fremgang. Forvandl "Jeg vil gerne blive bedre" til specifikke mål, du rent faktisk kan opnå.')])],-1)),(i(),l(g,null,{default:d(()=>[o(f,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BVagt%20m%C3%A5l%5D%20--%3E%20B%5BIngen%20klar%20handling%5D%0A%20%20%20%20B%20--%3E%20C%5BIngen%20fremskridt%5D%0A%0A%20%20%20%20D%5BSMART-m%C3%A5l%5D%20--%3E%20E%5BKlar%20handlingsplan%5D%0A%20%20%20%20E%20--%3E%20F%5BM%C3%A5lbar%20fremgang%5D%0A%20%20%20%20F%20--%3E%20G%5BPr%C3%A6station%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20G%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...m[0]||(m[0]=[s(" Loading... ",-1)])]),_:1})),m[4]||(m[4]=n('<h2 id="s-specifik" tabindex="-1">S - Specifik <a class="header-anchor" href="#s-specifik" aria-label="Permalink to &quot;S - Specifik&quot;">​</a></h2><p>Et specifikt mål besvarer disse spørgsmål:</p><ul><li><strong>Hvad</strong> er det præcist, jeg vil opnå?</li><li><strong>Hvor</strong> vil dette ske?</li><li><strong>Hvilke</strong> aspekter er involveret?</li></ul><h3 id="gør-mal-specifikke" tabindex="-1">Gør mål specifikke <a class="header-anchor" href="#gør-mal-specifikke" aria-label="Permalink to &quot;Gør mål specifikke&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Uklar</th><th>Bestemt</th></tr></thead><tbody><tr><td>&quot;Forbedr min pegeteknik&quot;</td><td>&quot;Forbedre min pegepræcision på grusoverflader på 7-9 meters afstand&quot;</td></tr><tr><td>&quot;Bliv mentalt stærkere&quot;</td><td>&quot;Udvikle en ensartet rutine før kast, som jeg bruger til hvert kast&quot;</td></tr><tr><td>&quot;Vind flere kampe&quot;</td><td>&quot;Vinder mindst 60% af mine konkurrencekampe i denne sæson&quot;</td></tr></tbody></table><h3 id="specificitetstjekliste" tabindex="-1">Specificitetstjekliste <a class="header-anchor" href="#specificitetstjekliste" aria-label="Permalink to &quot;Specificitetstjekliste&quot;">​</a></h3><ul><li>[ ] Kan en anden forstå præcis, hvad jeg prøver at gøre?</li><li>[ ] Har jeg defineret betingelserne (afstand, overflade, situation)?</li><li>[ ] Er der kun én fortolkning af dette mål?</li></ul><h2 id="m-malbar" tabindex="-1">M - Målbar <a class="header-anchor" href="#m-malbar" aria-label="Permalink to &quot;M - Målbar&quot;">​</a></h2><p>Hvis du ikke kan måle det, kan du ikke styre det. Målbare mål lader dig spore fremskridt og vide, hvornår du har haft succes.</p><h3 id="mader-at-male-petanque-mal-pa" tabindex="-1">Måder at måle petanque-mål på <a class="header-anchor" href="#mader-at-male-petanque-mal-pa" aria-label="Permalink to &quot;Måder at måle petanque-mål på&quot;">​</a></h3><p><strong>Kvantitative målinger:</strong></p><ul><li>Point scoret i øvelser (f.eks. 24/30)</li><li>Procentuel nøjagtighed (f.eks. 75 % hitrate)</li><li>Afstand fra målet (f.eks. gennemsnitlig 30 cm fra donkraften)</li><li>Konsistens (f.eks. 3 succesfulde sessioner i træk)</li></ul><p><strong>Brug af træningsøvelser som måleinstrumenter:</strong></p><table tabindex="0"><thead><tr><th>Bore</th><th>Hvad den måler</th><th>Måleksempel</th></tr></thead><tbody><tr><td>Skydestige</td><td>Skydepræcision under pres</td><td>Nå 10m inden for 30 kugler</td></tr><tr><td>Pegepræcision</td><td>Pegepræcision til zone</td><td>24/30 point</td></tr><tr><td>Afstandsvariation</td><td>Dybdekontrol</td><td>80% inden for 50 cm</td></tr></tbody></table><h3 id="sporing-af-dine-malinger" tabindex="-1">Sporing af dine målinger <a class="header-anchor" href="#sporing-af-dine-malinger" aria-label="Permalink to &quot;Sporing af dine målinger&quot;">​</a></h3><p>Hold en simpel logbog:</p><ul><li>Dato</li><li>Øvelse/motion</li><li>Score/resultat</li><li>Forhold (overflade, vejr)</li><li>Noter</li></ul><h2 id="a-opnaelig-men-udfordrende" tabindex="-1">A - Opnåelig (men udfordrende) <a class="header-anchor" href="#a-opnaelig-men-udfordrende" aria-label="Permalink to &quot;A - Opnåelig (men udfordrende)&quot;">​</a></h2><p>Mål skal udfordre dig uden at være umulige.</p><h3 id="at-finde-det-rigtige-niveau" tabindex="-1">At finde det rigtige niveau <a class="header-anchor" href="#at-finde-det-rigtige-niveau" aria-label="Permalink to &quot;At finde det rigtige niveau&quot;">​</a></h3><p><strong>For let:</strong> &quot;Øv én gang i denne måned&quot;</p><ul><li>Ingen vækst, ingen motivation</li></ul><p><strong>For svært:</strong> &quot;Gå aldrig glip af et skud&quot;</p><ul><li>Umuligt, fører til frustration</li></ul><p><strong>Lige præcist:</strong> &quot;Forbedr skydepræcisionen med 15 % på 8 uger&quot;</p><ul><li>Udfordrende, men realistisk med indsats</li></ul><h3 id="spørgsmal-til-at-teste-opnaelighed" tabindex="-1">Spørgsmål til at teste opnåelighed <a class="header-anchor" href="#spørgsmal-til-at-teste-opnaelighed" aria-label="Permalink to &quot;Spørgsmål til at teste opnåelighed&quot;">​</a></h3><ul><li>Har andre på mit niveau opnået dette?</li><li>Har jeg den nødvendige tid og de nødvendige ressourcer?</li><li>Er dette (for det meste) inden for min kontrol?</li><li>Er jeg villig til at gøre, hvad der kræves?</li></ul><h3 id="strækmal" tabindex="-1">Strækmål <a class="header-anchor" href="#strækmal" aria-label="Permalink to &quot;Strækmål&quot;">​</a></h3><p>Det er okay at have ambitiøse langsigtede mål. Bare sørg for, at dine kortsigtede mål er opnåelige skridt i retning af dem.</p><h2 id="r-relevant" tabindex="-1">R - Relevant <a class="header-anchor" href="#r-relevant" aria-label="Permalink to &quot;R - Relevant&quot;">​</a></h2><p>Dine mål skal stemme overens med dit større billede.</p><h3 id="relevansspørgsmal" tabindex="-1">Relevansspørgsmål <a class="header-anchor" href="#relevansspørgsmal" aria-label="Permalink to &quot;Relevansspørgsmål&quot;">​</a></h3><ul><li>Understøtter dette mål min samlede udvikling?</li><li>Er det den rigtige prioritet lige nu?</li><li>Passer dette med min tid og mine ressourcer til rådighed?</li><li>Er jeg oprigtigt motiveret af dette mål?</li></ul><h3 id="eksempel-kontrol-af-relevans" tabindex="-1">Eksempel: Kontrol af relevans <a class="header-anchor" href="#eksempel-kontrol-af-relevans" aria-label="Permalink to &quot;Eksempel: Kontrol af relevans&quot;">​</a></h3><p><strong>Situation:</strong> Du ønsker at konkurrere på nationalt niveau</p><p><strong>Relevante mål:</strong></p><ul><li>Forbedre skydepræcisionen (påvirker resultaterne direkte)</li><li>Udvikle mentale rutiner (hjælper i pressede situationer)</li><li>Øg træningsfrekvensen (opbygger færdigheder hurtigere)</li></ul><p><strong>Mindre relevante mål:</strong></p><ul><li>Lær trick shots (sjovt, men ikke konkurrencepræget)</li><li>Køb dyre nye boules (udstyr er ikke din begrænsende faktor)</li></ul><h2 id="t-tidsbegrænset" tabindex="-1">T - Tidsbegrænset <a class="header-anchor" href="#t-tidsbegrænset" aria-label="Permalink to &quot;T - Tidsbegrænset&quot;">​</a></h2><p>Deadlines skaber hastværk og muliggør planlægning.</p><h3 id="indstilling-af-tidsrammer" tabindex="-1">Indstilling af tidsrammer <a class="header-anchor" href="#indstilling-af-tidsrammer" aria-label="Permalink to &quot;Indstilling af tidsrammer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Måltype</th><th>Typisk tidsramme</th></tr></thead><tbody><tr><td>Langsigtet</td><td>1-3 år</td></tr><tr><td>Årlig</td><td>12 måneder</td></tr><tr><td>Kvartalsvis</td><td>3 måneder</td></tr><tr><td>Månedlig</td><td>4 uger</td></tr><tr><td>Ugentlig</td><td>7 dage</td></tr><tr><td>Session</td><td>Enkelt praksis</td></tr></tbody></table><h3 id="eksempel-pa-tidslinje" tabindex="-1">Eksempel på tidslinje <a class="header-anchor" href="#eksempel-pa-tidslinje" aria-label="Permalink to &quot;Eksempel på tidslinje&quot;">​</a></h3><p><strong>Langvarig (2 år):</strong> Kvalificér dig til landsholdsudtagelse</p><p><strong>Årlig:</strong> Placering i top 10 på regionale ranglister</p><p><strong>Kvartalsvis (Q1):</strong></p><ul><li>Etabler en fast træningsrutine</li><li>Forbedr skydepræcisionen til 70%</li></ul><p><strong>Månedligt (januar):</strong></p><ul><li>Uge 1: Vurder det nuværende niveau, sæt baselines</li><li>Uge 2-3: Fokus på skydeteknik</li><li>Uge 4: Test og mål fremskridt</li></ul><p><strong>Ugentlig:</strong></p><ul><li>Mandag: Teknisk skydesession</li><li>Onsdag: Pointing og spilsituationer</li><li>Fredag: Mental træning og visualisering</li><li>Weekend: Konkurrence- eller kamptræning</li></ul><h2 id="at-sætte-det-hele-sammen" tabindex="-1">At sætte det hele sammen <a class="header-anchor" href="#at-sætte-det-hele-sammen" aria-label="Permalink to &quot;At sætte det hele sammen&quot;">​</a></h2><h3 id="malsætningsark" tabindex="-1">Målsætningsark <a class="header-anchor" href="#malsætningsark" aria-label="Permalink to &quot;Målsætningsark&quot;">​</a></h3><p><strong>Mit mål (første udkast):</strong></p><hr><p><strong>Specifikt - Hvad præcist?</strong></p><hr><p><strong>Målbar - Hvordan ved jeg det?</strong></p><hr><p><strong>Opnåeligt - Er det realistisk?</strong></p><hr><p><strong>Relevant - Hvorfor er dette vigtigt?</strong></p><hr><p><strong>Tidsbestemt - Hvornår?</strong></p><hr><p><strong>Mit SMART-mål (endelig version):</strong></p><hr><h3 id="eksempel-færdiggjort" tabindex="-1">Eksempel færdiggjort <a class="header-anchor" href="#eksempel-færdiggjort" aria-label="Permalink to &quot;Eksempel færdiggjort&quot;">​</a></h3><p><strong>Første udkast:</strong> &quot;Bliv bedre til at skyde&quot;</p><p><strong>SMART-version:</strong> &quot;Inden den 30. april vil jeg opnå en score på 24/30 eller højere på Shooting Ladder-øvelsen (6-10 m med forhindringer) i tre på hinanden følgende træningssessioner, målt ud fra min træningslog.&quot;</p><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>SMARTE mål forvandler drømme til planer og planer til resultater.</p></blockquote><p>Tag dig tid til at formulere dine mål ordentligt. Et veldefineret mål er halvdelen af rejsen.</p>',75))])}]]);export{m as __pageData,p as default};
